import csv
import io


def parse_csv(raw_csv: str):
    csv.field_size_limit(max(csv.field_size_limit(), 2147483647))
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')

    try:
        columns = next(reader)
    except StopIteration:
        return {"columns": [], "rows": []}

    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    rows = list(reader)
    width = max([len(columns)] + [len(row) for row in rows])

    existing = set(columns)
    number = 1
    while len(columns) < width:
        name = f"extra_column_{number}"
        number += 1
        if name not in existing:
            columns.append(name)
            existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
